/**
 * @param {number} a
 * @param {number} b
 * @return {number}
 */
Foo.prototype.add = function(a, b) {
  return a + b;
};


/**
 * @param {number} a
 * @param {number} b
 * @return {number}
 */
Foo.prototype.sub = goog.abstractMethod;


/**
