    mainWindow.webContents.openDevTools();

    mainWindow.loadFile("index.html");

    mainWindow.webContents.on("did-finish-load", () => {
        mainWindow.webContents.executeJavaScript(`console.log("hello");`); // <--- this does not execute with electron-3.0.0-beta.1
    });

    mainWindow.once('ready-to-show', () => mainWindow.show());
}

app.on("ready", createMainWindow);

app.on("window-all-closed", () => {
    if (process.platform != "darwin")
        app.quit(); // macOS style
});

app.on("activate", () => {
    if (!mainWindow)
        createMainWindow(); // macOS style
});
```

Executing it with electron 3.0.0-beta.1 won't print anything in the console. With electron 2.0.4 you get "hello" message in console.

I made some other test like loading the page (`mainWindow.loadFile(...)`) after a timeout of one second, but nothing changed.
I also checked if the `did-finish-load` event is actually fired like this:
```javascript
    mainWindow.webContents.on("did-finish-load", () => {
        console.log("finish");
        mainWindow.webContents.executeJavaScript(`console.log("hello");`); // <--- this does not execute with electron-3.0.0-beta.1
    });
```
and `finish` gets printed out on main process, so the callback is actually executed.

another update: using `dom-ready` instead of `did-finish-load` works even with 3.0.0-beta.2 (javascript code is executed):

```javascript
    mainWindow.webContents.on("dom-ready", () => {
        console.log("finish");
        mainWindow.webContents.executeJavaScript(`console.log("hello");`); // <--- this does does execute even with electron-3.0.0-beta.x
    });
```
However this is not a suitable workaround in my real application because I need to execute my javascript from main process **after**  the `onload` event has been fired on rendering process. And according to documentation, the right one is [did-finish-load](https://electronjs.org/docs/api/web-contents#event-did-finish-load):

> Emitted when the navigation is done, i.e. the spinner of the tab has stopped spinning, and the onload event was dispatched

And again this works as expected in version 2.0.x

It looks like this applies to far more than the `Notification` API.
```js
// preload.js

function getGlobalNames() {
  return Object.getOwnPropertyNames(global).filter(key => typeof global[key] == "function").sort()
}

const globalsSync = getGlobalNames()

setTimeout(() => {
  const globalsAsync = getGlobalNames()
  const newGlobals = globalsAsync.filter(name => !globalsSync.includes(name))

  console.log(`sync: ${globalsSync.length}`)
  console.log(`async: ${globalsAsync.length}`)
  console.log(`async only (${newGlobals.length}): ${newGlobals.join(", ")}`)
})
```

